mapper.select:
SELECT FROM tb_customer_address a JOIN tb_customer c ON c.customer_seq = a.customer_seq WHERE a.customer_seq = #{customerSeq}
AND a.address_seq <> #{exceptAddressSeq}
ORDER BY a.sort_order, a.address_seq LIMIT 1
